#include &lt;cstdio&gt; #include &lt;cstring&gt; #include &lt;iostream&gt; #include &lt;algorithm&gt; using namespace std; #define INF 0x3f3f3f3f int a[30]; int cal(int n) { int sum = ; int i; for (i = 1; i &lt;= n; i++) { /* code */ sum = abs(sum - a[i]); } return sum; } void parray(int a[], int len) { int i; for (i = 1; i &lt;= len; i++) { cout &lt;&lt; a[i] &lt;&lt; " "; } cout &lt;&lt; endl; } void cp(int a[], int b[], int n) { int i; for (i = ; i &lt;= n; i++) { a[i] = b[i]; } } int main(int argc, const char *argv[]) { int i; for (i = 1; i &lt;= 30; i++) { a[i] = i; } int n; int maxa[30], mina[30]; while (~scanf("%d", &n)) { int max = -INF; int min = INF; if (n == 1) { cout &lt;&lt; "1 1" &lt;&lt; endl; cout &lt;&lt; "1" &lt;&lt; endl &lt;&lt; "1" &lt;&lt; endl; continue; } while (next_permutation(a+1, a+n+1)) { /* code */ int temp = cal(n); if (temp &gt;= max) { max = temp; cp(maxa, a, n); } if (temp &lt;= min) { min = temp; cp(mina, a, n); } } cout &lt;&lt; min &lt;&lt; " " &lt;&lt; max &lt;&lt; endl; for (i = 1; i &lt;= n; i++) { cout &lt;&lt; mina[i] &lt;&lt; " "; } cout &lt;&lt; endl; for (i = 1; i &lt;= n; i++) { cout &lt;&lt; maxa[i] &lt;&lt; " "; } cout &lt;&lt; endl; } return ; } 代码如上。

